final_template:
AWSTemplateFormatVersion: '2010-09-09'
Description: Creates an AWS IoT Core device-onboarding policy through a Lambda-backed custom resource (Node.js 24.x). The policy lets devices connect, publish, receive and subscribe only within topics scoped to their own thing name.

Parameters:
  TopicPrefix:
    Type: String
    Default: devices
    AllowedPattern: '^[a-zA-Z0-9_-]+$'
    ConstraintDescription: Must contain only alphanumeric characters, underscores or hyphens.
    Description: Top-level MQTT topic prefix. Devices are scoped to <TopicPrefix>/<ThingName>/*.

Resources:
  IoTPolicyProviderLogGroup:
    Type: AWS::Logs::LogGroup
    Properties:
      LogGroupName: !Sub '/aws/lambda/${AWS::StackName}-iot-policy-provider'
      RetentionInDays: 14
      Tags:
        - Key: Purpose
          Value: iot-device-onboarding
        - Key: StackName
          Value: !Ref 'AWS::StackName'

  IoTPolicyProviderRole:
    Type: AWS::IAM::Role
    Properties:
      Description: Execution role for the IoT device-onboarding policy custom-resource provider.
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: lambda.amazonaws.com
            Action: sts:AssumeRole
      ManagedPolicyArns:
        - !Sub 'arn:${AWS::Partition}:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole'
      Policies:
        - PolicyName: IoTDevicePolicyManagement
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Sid: ManageOnboardingPolicy
                Effect: Allow
                Action:
                  - iot:CreatePolicy
                  - iot:GetPolicy
                  - iot:DeletePolicy
                  - iot:CreatePolicyVersion
                  - iot:DeletePolicyVersion
                  - iot:ListPolicyVersions
                  - iot:ListTargetsForPolicy
                Resource: !Sub 'arn:${AWS::Partition}:iot:${AWS::Region}:${AWS::AccountId}:policy/${AWS::StackName}-device-onboarding-policy'
              - Sid: DetachOnboardingPolicyFromCertificates
                Effect: Allow
                Action:
                  - iot:DetachPolicy
                Resource:
                  - !Sub 'arn:${AWS::Partition}:iot:${AWS::Region}:${AWS::AccountId}:policy/${AWS::StackName}-device-onboarding-policy'
                  - !Sub 'arn:${AWS::Partition}:iot:${AWS::Region}:${AWS::AccountId}:cert/*'
      Tags:
        - Key: Purpose
          Value: iot-device-onboarding
        - Key: StackName
          Value: !Ref 'AWS::StackName'

  IoTPolicyProviderFunction:
    Type: AWS::Lambda::Function
    Properties:
      FunctionName: !Sub '${AWS::StackName}-iot-policy-provider'
      Description: Custom resource provider that manages the IoT Core device-onboarding policy.
      Runtime: nodejs24.x
      Handler: index.handler
      Role: !GetAtt IoTPolicyProviderRole.Arn
      Timeout: 120
      MemorySize: 128
      Architectures:
        - arm64
      Code:
        ZipFile: |
          'use strict';

          const {
            IoTClient,
            CreatePolicyCommand,
            GetPolicyCommand,
            DeletePolicyCommand,
            CreatePolicyVersionCommand,
            DeletePolicyVersionCommand,
            ListPolicyVersionsCommand,
            ListTargetsForPolicyCommand,
            DetachPolicyCommand,
          } = require('@aws-sdk/client-iot');

          const iot = new IoTClient({});
          const THING_VAR = '${iot:Connection.Thing.ThingName}';
          const MAX_POLICY_VERSIONS = 5;

          function buildPolicyDocument(props) {
            const base = `arn:${props.Partition}:iot:${props.Region}:${props.AccountId}`;
            const prefix = props.TopicPrefix;
            return JSON.stringify({
              Version: '2012-10-17',
              Statement: [
                {
                  Effect: 'Allow',
                  Action: ['iot:Connect'],
                  Resource: [`${base}:client/${THING_VAR}`],
                  Condition: {
                    Bool: { 'iot:Connection.Thing.IsAttached': 'true' },
                  },
                },
                {
                  Effect: 'Allow',
                  Action: ['iot:Publish', 'iot:Receive'],
                  Resource: [`${base}:topic/${prefix}/${THING_VAR}/*`],
                },
                {
                  Effect: 'Allow',
                  Action: ['iot:Subscribe'],
                  Resource: [`${base}:topicfilter/${prefix}/${THING_VAR}/*`],
                },
              ],
            });
          }

          function validateProps(props) {
            const required = ['PolicyName', 'TopicPrefix', 'Region', 'AccountId', 'Partition'];
            const missing = required.filter((k) => !props[k]);
            if (missing.length > 0) {
              throw new Error(`Missing required properties: ${missing.join(', ')}`);
            }
            if (!/^[a-zA-Z0-9_-]+$/.test(props.TopicPrefix)) {
              throw new Error(`Invalid TopicPrefix: ${props.TopicPrefix}`);
            }
          }

          function isNotFound(err) {
            return err && (err.name === 'ResourceNotFoundException' || err.$metadata?.httpStatusCode === 404);
          }

          async function policyExists(policyName) {
            try {
              return await iot.send(new GetPolicyCommand({ policyName }));
            } catch (err) {
              if (isNotFound(err)) return null;
              throw err;
            }
          }

          async function createPolicy(props) {
            const res = await iot.send(new CreatePolicyCommand({
              policyName: props.PolicyName,
              policyDocument: buildPolicyDocument(props),
            }));
            return { PolicyName: res.policyName, PolicyArn: res.policyArn };
          }

          async function pruneOldVersions(policyName) {
            const res = await iot.send(new ListPolicyVersionsCommand({ policyName }));
            const versions = (res.policyVersions || []).filter((v) => !v.isDefaultVersion);
            const total = (res.policyVersions || []).length;
            if (total < MAX_POLICY_VERSIONS) return;
            versions.sort((a, b) => new Date(a.createDate) - new Date(b.createDate));
            const toDelete = versions.slice(0, total - MAX_POLICY_VERSIONS + 1);
            for (const v of toDelete) {
              console.log(`Deleting old policy version ${v.versionId} of ${policyName}`);
              await iot.send(new DeletePolicyVersionCommand({ policyName, policyVersionId: v.versionId }));
            }
          }

          async function updatePolicy(props) {
            const existing = await policyExists(props.PolicyName);
            if (!existing) {
              console.log(`Policy ${props.PolicyName} not found during update; creating it.`);
              return createPolicy(props);
            }
            await pruneOldVersions(props.PolicyName);
            await iot.send(new CreatePolicyVersionCommand({
              policyName: props.PolicyName,
              policyDocument: buildPolicyDocument(props),
              setAsDefault: true,
            }));
            return { PolicyName: existing.policyName, PolicyArn: existing.policyArn };
          }

          async function detachAllTargets(policyName) {
            let marker;
            do {
              const res = await iot.send(new ListTargetsForPolicyCommand({ policyName, marker, pageSize: 250 }));
              for (const target of res.targets || []) {
                console.log(`Detaching ${policyName} from ${target}`);
                try {
                  await iot.send(new DetachPolicyCommand({ policyName, target }));
                } catch (err) {
                  if (!isNotFound(err)) throw err;
                }
              }
              marker = res.nextMarker;
            } while (marker);
          }

          async function deletePolicy(policyName) {
            const existing = await policyExists(policyName);
            if (!existing) {
              console.log(`Policy ${policyName} does not exist; nothing to delete.`);
              return;
            }
            await detachAllTargets(policyName);
            const res = await iot.send(new ListPolicyVersionsCommand({ policyName }));
            for (const v of res.policyVersions || []) {
              if (!v.isDefaultVersion) {
                await iot.send(new DeletePolicyVersionCommand({ policyName, policyVersionId: v.versionId }));
              }
            }
            try {
              await iot.send(new DeletePolicyCommand({ policyName }));
              console.log(`Deleted policy ${policyName}`);
            } catch (err) {
              if (!isNotFound(err)) throw err;
            }
          }

          async function sendResponse(event, context, status, reason, physicalResourceId, data) {
            const body = JSON.stringify({
              Status: status,
              Reason: reason || `See CloudWatch Logs: ${context.logGroupName} / ${context.logStreamName}`,
              PhysicalResourceId: physicalResourceId || context.logStreamName,
              StackId: event.StackId,
              RequestId: event.RequestId,
              LogicalResourceId: event.LogicalResourceId,
              NoEcho: false,
              Data: data || {},
            });
            console.log(`Sending ${status} response to CloudFormation`);
            const res = await fetch(event.ResponseURL, {
              method: 'PUT',
              headers: {
                'Content-Type': '',
                'Content-Length': Buffer.byteLength(body).toString(),
              },
              body,
            });
            if (!res.ok) {
              throw new Error(`Failed to send response: HTTP ${res.status} ${res.statusText}`);
            }
          }

          exports.handler = async (event, context) => {
            console.log('Received event:', JSON.stringify({ ...event, ResponseURL: '[redacted]' }));

            let responded = false;
            const respond = async (status, reason, physicalId, data) => {
              if (responded) return;
              responded = true;
              await sendResponse(event, context, status, reason, physicalId, data);
            };

            const guardMs = Math.max(context.getRemainingTimeInMillis() - 5000, 1000);
            let timer;
            const timeoutGuard = new Promise((resolve) => {
              timer = setTimeout(async () => {
                console.error('Handler is about to time out; sending FAILED response.');
                try {
                  await respond('FAILED', 'Custom resource handler timed out before completing.', event.PhysicalResourceId);
                } catch (err) {
                  console.error('Error sending timeout response:', err);
                }
                resolve();
              }, guardMs);
            });

            const work = (async () => {
              try {
                const props = event.ResourceProperties || {};
                let result;
                switch (event.RequestType) {
                  case 'Create': {
                    validateProps(props);
                    result = await createPolicy(props);
                    await respond('SUCCESS', 'IoT policy created', result.PolicyName, result);
                    break;
                  }
                  case 'Update': {
                    validateProps(props);
                    result = await updatePolicy(props);
                    await respond('SUCCESS', 'IoT policy updated', result.PolicyName, result);
                    break;
                  }
                  case 'Delete': {
                    const policyName = event.PhysicalResourceId;
                    const expectedName = props.PolicyName;
                    if (policyName && policyName === expectedName) {
                      await deletePolicy(policyName);
                    } else if (policyName && /-device-onboarding-policy$/.test(policyName)) {
                      await deletePolicy(policyName);
                    } else {
                      console.log(`PhysicalResourceId ${policyName} is not a managed policy; skipping delete.`);
                    }
                    await respond('SUCCESS', 'IoT policy deleted', policyName, {});
                    break;
                  }
                  default:
                    throw new Error(`Unsupported RequestType: ${event.RequestType}`);
                }
              } catch (err) {
                console.error('Handler error:', err);
                const reason = `${event.RequestType} failed: ${err.name || 'Error'}: ${err.message}`.slice(0, 1000);
                try {
                  await respond('FAILED', reason, event.PhysicalResourceId, {});
                } catch (sendErr) {
                  console.error('Error sending FAILED response:', sendErr);
                }
              }
            })();

            await Promise.race([work, timeoutGuard]);
            clearTimeout(timer);
          };
      Tags:
        - Key: Purpose
          Value: iot-device-onboarding
        - Key: StackName
          Value: !Ref 'AWS::StackName'

  IoTDevicePolicy:
    Type: Custom::IoTDevicePolicy
    DependsOn: IoTPolicyProviderLogGroup
    Properties:
      ServiceToken: !GetAtt IoTPolicyProviderFunction.Arn
      PolicyName: !Sub '${AWS::StackName}-device-onboarding-policy'
      TopicPrefix: !Ref TopicPrefix
      Region: !Ref 'AWS::Region'
      AccountId: !Ref 'AWS::AccountId'
      Partition: !Ref 'AWS::Partition'

Outputs:
  PolicyName:
    Description: Generated IoT Core device onboarding policy name
    Value: !GetAtt IoTDevicePolicy.PolicyName
    Export:
      Name: !Sub '${AWS::StackName}-IoTPolicyName'
  PolicyArn:
    Description: ARN of the generated IoT Core device onboarding policy, for use in onboarding or provisioning-template steps
    Value: !GetAtt IoTDevicePolicy.PolicyArn

AWSTemplateFormatVersion: '2010-09-09'
Description: Creates a Cedar-based Amazon Verified Permissions policy store for a bookstore application, with strict schema validation, static access policies, and an SSM parameter publishing the policy store ID.

Resources:
  BookstorePolicyStore:
    Type: AWS::VerifiedPermissions::PolicyStore
    Properties:
      Description: Bookstore application Cedar policy store
      ValidationSettings:
        Mode: STRICT
      Schema:
        CedarJson: |
          {
            "Bookstore": {
              "entityTypes": {
                "Role": {
                  "shape": {
                    "type": "Record",
                    "attributes": {}
                  }
                },
                "User": {
                  "memberOfTypes": ["Role"],
                  "shape": {
                    "type": "Record",
                    "attributes": {
                      "yearsmember": {
                        "type": "Long",
                        "required": false
                      }
                    }
                  }
                },
                "Book": {
                  "shape": {
                    "type": "Record",
                    "attributes": {
                      "owner": {
                        "type": "Entity",
                        "name": "User",
                        "required": true
                      }
                    }
                  }
                }
              },
              "actions": {
                "View": {
                  "appliesTo": {
                    "principalTypes": ["User"],
                    "resourceTypes": ["Book"],
                    "context": {
                      "type": "Record",
                      "attributes": {
                        "region": {
                          "type": "String",
                          "required": true
                        }
                      }
                    }
                  }
                },
                "ViewWithPremiumOffers": {
                  "appliesTo": {
                    "principalTypes": ["User"],
                    "resourceTypes": ["Book"],
                    "context": {
                      "type": "Record",
                      "attributes": {
                        "region": {
                          "type": "String",
                          "required": true
                        }
                      }
                    }
                  }
                }
              }
            }
          }

  PolicyStoreIdParameter:
    Type: AWS::SSM::Parameter
    Properties:
      Name: !Sub '/${AWS::StackName}/bookstore/policy-store-id'
      Type: String
      Value: !GetAtt BookstorePolicyStore.PolicyStoreId
      Description: Amazon Verified Permissions policy store ID for the bookstore application

  AdminViewAllBooksPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !GetAtt BookstorePolicyStore.PolicyStoreId
      Definition:
        Static:
          Description: Permit users in the Admin role to view any book
          Statement: |
            permit (
              principal in Bookstore::Role::"Admin",
              action == Bookstore::Action::"View",
              resource
            );

  ForbidSpecificAdminViewPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !GetAtt BookstorePolicyStore.PolicyStoreId
      Definition:
        Static:
          Description: Forbid the specific administrator Dante from viewing books, overriding the admin permit
          Statement: |
            forbid (
              principal == Bookstore::User::"Dante",
              action == Bookstore::Action::"View",
              resource
            );

  PublisherViewOwnBooksPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !GetAtt BookstorePolicyStore.PolicyStoreId
      Definition:
        Static:
          Description: Permit users in the Publisher role to view only the books they own
          Statement: |
            permit (
              principal in Bookstore::Role::"Publisher",
              action == Bookstore::Action::"View",
              resource
            )
            when { resource.owner == principal };

  SpecificUserSpecificBookPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !GetAtt BookstorePolicyStore.PolicyStoreId
      Definition:
        Static:
          Description: Permit the specific user Alice to view one specific book
          Statement: |
            permit (
              principal == Bookstore::User::"Alice",
              action == Bookstore::Action::"View",
              resource == Bookstore::Book::"978-0-3064-0615-7"
            );

  CustomerPremiumOffersPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !GetAtt BookstorePolicyStore.PolicyStoreId
      Definition:
        Static:
          Description: Permit customers with two or more years of membership to view premium offers
          Statement: |
            permit (
              principal in Bookstore::Role::"Customer",
              action == Bookstore::Action::"ViewWithPremiumOffers",
              resource
            )
            when { principal has yearsmember && principal.yearsmember >= 2 };

  ForbidNewCustomerPremiumOffersPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !GetAtt BookstorePolicyStore.PolicyStoreId
      Definition:
        Static:
          Description: Forbid customers with less than two years of membership from viewing premium offers
          Statement: |
            forbid (
              principal in Bookstore::Role::"Customer",
              action == Bookstore::Action::"ViewWithPremiumOffers",
              resource
            )
            unless { principal has yearsmember && principal.yearsmember >= 2 };

  ForbidNonUSRegionPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !GetAtt BookstorePolicyStore.PolicyStoreId
      Definition:
        Static:
          Description: Forbid View and ViewWithPremiumOffers whenever the request region is not the United States
          Statement: |
            forbid (
              principal,
              action in [Bookstore::Action::"View", Bookstore::Action::"ViewWithPremiumOffers"],
              resource
            )
            when { context.region != "US" };

Outputs:
  PolicyStoreId:
    Description: ID of the bookstore Verified Permissions policy store
    Value: !GetAtt BookstorePolicyStore.PolicyStoreId
    Export:
      Name: !Sub '${AWS::StackName}-PolicyStoreId'
  PolicyStoreArn:
    Description: ARN of the bookstore Verified Permissions policy store
    Value: !GetAtt BookstorePolicyStore.Arn
    Export:
      Name: !Sub '${AWS::StackName}-PolicyStoreArn'
  PolicyStoreIdParameterName:
    Description: Name of the SSM parameter holding the policy store ID
    Value: !Ref PolicyStoreIdParameter
    Export:
      Name: !Sub '${AWS::StackName}-PolicyStoreIdParameterName'

AWSTemplateFormatVersion: '2010-09-09'
Description: Self-contained AWS AppSync GraphQL Todo API (TodoAPIwithJs) using API key authentication, JavaScript pipeline resolvers, and a DynamoDB table with an owner global secondary index, plus real-time subscriptions for create, update and delete events.

Resources:
  TodoTable:
    Type: AWS::DynamoDB::Table
    DeletionPolicy: Retain
    UpdateReplacePolicy: Retain
    Properties:
      BillingMode: PAY_PER_REQUEST
      AttributeDefinitions:
        - AttributeName: id
          AttributeType: S
        - AttributeName: owner
          AttributeType: S
      KeySchema:
        - AttributeName: id
          KeyType: HASH
      GlobalSecondaryIndexes:
        - IndexName: owner-index
          KeySchema:
            - AttributeName: owner
              KeyType: HASH
          Projection:
            ProjectionType: ALL
      SSESpecification:
        SSEEnabled: true
      PointInTimeRecoverySpecification:
        PointInTimeRecoveryEnabled: true
      Tags:
        - Key: Application
          Value: TodoAPIwithJs
        - Key: Environment
          Value: dev

  AppSyncDynamoDBRole:
    Type: AWS::IAM::Role
    Properties:
      Description: Allows AppSync to access the Todo DynamoDB table and its owner index.
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: appsync.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: TodoTableAccess
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action:
                  - dynamodb:GetItem
                  - dynamodb:PutItem
                  - dynamodb:UpdateItem
                  - dynamodb:DeleteItem
                  - dynamodb:Query
                  - dynamodb:Scan
                Resource:
                  - !GetAtt TodoTable.Arn
                  - !Sub '${TodoTable.Arn}/index/*'
      Tags:
        - Key: Application
          Value: TodoAPIwithJs
        - Key: Environment
          Value: dev

  AppSyncLoggingRole:
    Type: AWS::IAM::Role
    Properties:
      Description: Allows AppSync to push logs to CloudWatch Logs.
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: appsync.amazonaws.com
            Action: sts:AssumeRole
      ManagedPolicyArns:
        - arn:aws:iam::aws:policy/service-role/AWSAppSyncPushToCloudWatchLogs
      Tags:
        - Key: Application
          Value: TodoAPIwithJs
        - Key: Environment
          Value: dev

  TodoApi:
    Type: AWS::AppSync::GraphQLApi
    Properties:
      Name: TodoAPIwithJs
      AuthenticationType: API_KEY
      XrayEnabled: true
      LogConfig:
        CloudWatchLogsRoleArn: !GetAtt AppSyncLoggingRole.Arn
        FieldLogLevel: ERROR
        ExcludeVerboseContent: true
      Tags:
        - Key: Application
          Value: TodoAPIwithJs
        - Key: Environment
          Value: dev

  TodoApiKey:
    Type: AWS::AppSync::ApiKey
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Description: API key for the TodoAPIwithJs GraphQL API

  TodoSchema:
    Type: AWS::AppSync::GraphQLSchema
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Definition: |
        schema {
          query: Query
          mutation: Mutation
          subscription: Subscription
        }

        type Todo {
          id: ID!
          owner: String!
          title: String!
          description: String
          completed: Boolean
          createdAt: AWSDateTime
          updatedAt: AWSDateTime
        }

        type TodoConnection {
          items: [Todo]
          nextToken: String
        }

        input CreateTodoInput {
          owner: String!
          title: String!
          description: String
          completed: Boolean
        }

        input UpdateTodoInput {
          id: ID!
          owner: String
          title: String
          description: String
          completed: Boolean
        }

        input DeleteTodoInput {
          id: ID!
        }

        type Query {
          getTodo(id: ID!): Todo
          listTodos(limit: Int, nextToken: String): TodoConnection
          queryTodosByOwner(owner: String!, limit: Int, nextToken: String): TodoConnection
        }

        type Mutation {
          createTodo(input: CreateTodoInput!): Todo
          updateTodo(input: UpdateTodoInput!): Todo
          deleteTodo(input: DeleteTodoInput!): Todo
        }

        type Subscription {
          onCreateTodo: Todo @aws_subscribe(mutations: ["createTodo"])
          onUpdateTodo: Todo @aws_subscribe(mutations: ["updateTodo"])
          onDeleteTodo: Todo @aws_subscribe(mutations: ["deleteTodo"])
        }

  TodoTableDataSource:
    Type: AWS::AppSync::DataSource
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Name: TodoTableDataSource
      Description: DynamoDB data source for the Todo table
      Type: AMAZON_DYNAMODB
      ServiceRoleArn: !GetAtt AppSyncDynamoDBRole.Arn
      DynamoDBConfig:
        TableName: !Ref TodoTable
        AwsRegion: !Ref AWS::Region

  CreateTodoFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Name: CreateTodoFunction
      Description: Creates a Todo item with DynamoDB PutItem
      DataSourceName: !GetAtt TodoTableDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const input = ctx.args.input;
          const id = util.autoId();
          const now = util.time.nowISO8601();
          const item = {
            owner: input.owner,
            title: input.title,
            completed: input.completed === undefined || input.completed === null ? false : input.completed,
            createdAt: now,
            updatedAt: now,
          };
          if (input.description !== undefined && input.description !== null) {
            item.description = input.description;
          }
          return {
            operation: 'PutItem',
            key: util.dynamodb.toMapValues({ id }),
            attributeValues: util.dynamodb.toMapValues(item),
            condition: { expression: 'attribute_not_exists(id)' },
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  GetTodoFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Name: GetTodoFunction
      Description: Retrieves a Todo item with DynamoDB GetItem
      DataSourceName: !GetAtt TodoTableDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          return {
            operation: 'GetItem',
            key: util.dynamodb.toMapValues({ id: ctx.args.id }),
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  UpdateTodoFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Name: UpdateTodoFunction
      Description: Updates an existing Todo item with DynamoDB UpdateItem
      DataSourceName: !GetAtt TodoTableDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const input = ctx.args.input;
          const values = { updatedAt: util.time.nowISO8601() };
          for (const [key, value] of Object.entries(input)) {
            if (key !== 'id' && value !== undefined && value !== null) {
              values[key] = value;
            }
          }
          const expressionNames = {};
          const expressionValues = {};
          const setClauses = [];
          for (const [key, value] of Object.entries(values)) {
            expressionNames[`#${key}`] = key;
            expressionValues[`:${key}`] = value;
            setClauses.push(`#${key} = :${key}`);
          }
          return {
            operation: 'UpdateItem',
            key: util.dynamodb.toMapValues({ id: input.id }),
            update: {
              expression: `SET ${setClauses.join(', ')}`,
              expressionNames,
              expressionValues: util.dynamodb.toMapValues(expressionValues),
            },
            condition: { expression: 'attribute_exists(id)' },
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  DeleteTodoFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Name: DeleteTodoFunction
      Description: Deletes a Todo item with DynamoDB DeleteItem and returns the deleted item
      DataSourceName: !GetAtt TodoTableDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          return {
            operation: 'DeleteItem',
            key: util.dynamodb.toMapValues({ id: ctx.args.input.id }),
            condition: { expression: 'attribute_exists(id)' },
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  ListTodosFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Name: ListTodosFunction
      Description: Lists Todo items with a paginated DynamoDB Scan
      DataSourceName: !GetAtt TodoTableDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const request = {
            operation: 'Scan',
            limit: ctx.args.limit ? ctx.args.limit : 20,
          };
          if (ctx.args.nextToken) {
            request.nextToken = ctx.args.nextToken;
          }
          return request;
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return {
            items: ctx.result.items,
            nextToken: ctx.result.nextToken,
          };
        }

  QueryTodosByOwnerFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Name: QueryTodosByOwnerFunction
      Description: Queries Todo items by owner using the owner-index GSI
      DataSourceName: !GetAtt TodoTableDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const request = {
            operation: 'Query',
            index: 'owner-index',
            query: {
              expression: '#owner = :owner',
              expressionNames: { '#owner': 'owner' },
              expressionValues: util.dynamodb.toMapValues({ ':owner': ctx.args.owner }),
            },
            limit: ctx.args.limit ? ctx.args.limit : 20,
          };
          if (ctx.args.nextToken) {
            request.nextToken = ctx.args.nextToken;
          }
          return request;
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return {
            items: ctx.result.items,
            nextToken: ctx.result.nextToken,
          };
        }

  CreateTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoSchema
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      TypeName: Mutation
      FieldName: createTodo
      Kind: PIPELINE
      PipelineConfig:
        Functions:
          - !GetAtt CreateTodoFunction.FunctionId
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.prev.result;
        }

  UpdateTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoSchema
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
