Outputs:
  GraphQLApiId:
    Description: ID of the AppSync GraphQL API
    Value: !GetAtt TodoApi.ApiId
  GraphQLApiArn:
    Description: ARN of the AppSync GraphQL API
    Value: !GetAtt TodoApi.Arn
  GraphQLApiUrl:
    Description: GraphQL endpoint URL
    Value: !GetAtt TodoApi.GraphQLUrl
  GraphQLRealtimeUrl:
    Description: Real-time WebSocket endpoint URL for subscriptions
    Value: !GetAtt TodoApi.RealtimeUrl
  GraphQLApiKey:
    Description: API key used to authenticate requests
    Value: !GetAtt TodoApiKey.ApiKey
  TodoTableName:
    Description: Name of the DynamoDB Todo table
    Value: !Ref TodoTable
  TodoTableArn:
    Description: ARN of the DynamoDB Todo table
    Value: !GetAtt TodoTable.Arn

AWSTemplateFormatVersion: '2010-09-09'
Description: Simple to-do list GraphQL API on AWS AppSync with JavaScript resolvers, backed by a DynamoDB table and protected by an API key.

Resources:
  TodoTable:
    Type: AWS::DynamoDB::Table
    DeletionPolicy: Retain
    UpdateReplacePolicy: Retain
    Properties:
      TableName: !Sub '${AWS::StackName}-todos'
      BillingMode: PAY_PER_REQUEST
      AttributeDefinitions:
        - AttributeName: id
          AttributeType: S
        - AttributeName: owner
          AttributeType: S
        - AttributeName: createdAt
          AttributeType: S
      KeySchema:
        - AttributeName: id
          KeyType: HASH
      GlobalSecondaryIndexes:
        - IndexName: byOwner
          KeySchema:
            - AttributeName: owner
              KeyType: HASH
            - AttributeName: createdAt
              KeyType: RANGE
          Projection:
            ProjectionType: ALL
      PointInTimeRecoverySpecification:
        PointInTimeRecoveryEnabled: true
      SSESpecification:
        SSEEnabled: true
      Tags:
        - Key: Application
          Value: SimpleTodoAPI

  AppSyncDynamoDBRole:
    Type: AWS::IAM::Role
    Properties:
      Description: Service role assumed by AppSync to read and write the to-do table
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: appsync.amazonaws.com
            Action: sts:AssumeRole
            Condition:
              StringEquals:
                aws:SourceAccount: !Ref AWS::AccountId
      Policies:
        - PolicyName: TodoTableAccess
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action:
                  - dynamodb:GetItem
                  - dynamodb:PutItem
                  - dynamodb:UpdateItem
                  - dynamodb:DeleteItem
                  - dynamodb:Query
                  - dynamodb:Scan
                Resource:
                  - !GetAtt TodoTable.Arn
                  - !Sub '${TodoTable.Arn}/index/*'
      Tags:
        - Key: Application
          Value: SimpleTodoAPI

  SimpleTodoApi:
    Type: AWS::AppSync::GraphQLApi
    Properties:
      Name: SimpleTodoAPI
      AuthenticationType: API_KEY
      Tags:
        - Key: Application
          Value: SimpleTodoAPI

  SimpleTodoApiKey:
    Type: AWS::AppSync::ApiKey
    Properties:
      ApiId: !GetAtt SimpleTodoApi.ApiId
      Description: API key for testing the SimpleTodoAPI GraphQL API

  TodoSchema:
    Type: AWS::AppSync::GraphQLSchema
    Properties:
      ApiId: !GetAtt SimpleTodoApi.ApiId
      Definition: |
        schema {
          query: Query
          mutation: Mutation
        }

        type Todo {
          id: ID!
          owner: String!
          title: String!
          description: String
          completed: Boolean!
          createdAt: AWSDateTime!
          updatedAt: AWSDateTime!
        }

        type TodoConnection {
          items: [Todo!]!
          nextToken: String
        }

        input CreateTodoInput {
          owner: String!
          title: String!
          description: String
          completed: Boolean
        }

        input UpdateTodoInput {
          id: ID!
          title: String
          description: String
          completed: Boolean
        }

        type Query {
          getTodo(id: ID!): Todo
          listTodos(limit: Int, nextToken: String): TodoConnection!
          todosByOwner(owner: String!, limit: Int, nextToken: String): TodoConnection!
        }

        type Mutation {
          createTodo(input: CreateTodoInput!): Todo
          updateTodo(input: UpdateTodoInput!): Todo
          deleteTodo(id: ID!): Todo
        }

  TodoDataSource:
    Type: AWS::AppSync::DataSource
    Properties:
      ApiId: !GetAtt SimpleTodoApi.ApiId
      Name: TodoTableDataSource
      Description: DynamoDB data source for to-do items
      Type: AMAZON_DYNAMODB
      ServiceRoleArn: !GetAtt AppSyncDynamoDBRole.Arn
      DynamoDBConfig:
        TableName: !Ref TodoTable
        AwsRegion: !Ref AWS::Region

  CreateTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoSchema
    Properties:
      ApiId: !GetAtt SimpleTodoApi.ApiId
      TypeName: Mutation
      FieldName: createTodo
      DataSourceName: !GetAtt TodoDataSource.Name
      Kind: UNIT
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const input = ctx.args.input;
          const id = util.autoId();
          const now = util.time.nowISO8601();
          const item = {
            owner: input.owner,
            title: input.title,
            completed: input.completed === true,
            createdAt: now,
            updatedAt: now,
          };
          if (input.description !== undefined && input.description !== null) {
            item.description = input.description;
          }
          return {
            operation: 'PutItem',
            key: util.dynamodb.toMapValues({ id: id }),
            attributeValues: util.dynamodb.toMapValues(item),
            condition: {
              expression: 'attribute_not_exists(#id)',
              expressionNames: { '#id': 'id' },
            },
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  UpdateTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoSchema
    Properties:
      ApiId: !GetAtt SimpleTodoApi.ApiId
      TypeName: Mutation
      FieldName: updateTodo
      DataSourceName: !GetAtt TodoDataSource.Name
      Kind: UNIT
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const input = ctx.args.input;
          const fields = ['title', 'description', 'completed'];
          const setParts = ['#updatedAt = :updatedAt'];
          const names = { '#id': 'id', '#updatedAt': 'updatedAt' };
          const values = { ':updatedAt': util.time.nowISO8601() };

          for (const field of fields) {
            if (input[field] !== undefined && input[field] !== null) {
              setParts.push('#' + field + ' = :' + field);
              names['#' + field] = field;
              values[':' + field] = input[field];
            }
          }

          return {
            operation: 'UpdateItem',
            key: util.dynamodb.toMapValues({ id: input.id }),
            update: {
              expression: 'SET ' + setParts.join(', '),
              expressionNames: names,
              expressionValues: util.dynamodb.toMapValues(values),
            },
            condition: {
              expression: 'attribute_exists(#id)',
            },
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  DeleteTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoSchema
    Properties:
      ApiId: !GetAtt SimpleTodoApi.ApiId
      TypeName: Mutation
      FieldName: deleteTodo
      DataSourceName: !GetAtt TodoDataSource.Name
      Kind: UNIT
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          return {
            operation: 'DeleteItem',
            key: util.dynamodb.toMapValues({ id: ctx.args.id }),
            condition: {
              expression: 'attribute_exists(#id)',
              expressionNames: { '#id': 'id' },
            },
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  GetTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoSchema
    Properties:
      ApiId: !GetAtt SimpleTodoApi.ApiId
      TypeName: Query
      FieldName: getTodo
      DataSourceName: !GetAtt TodoDataSource.Name
      Kind: UNIT
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          return {
            operation: 'GetItem',
            key: util.dynamodb.toMapValues({ id: ctx.args.id }),
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  ListTodosResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoSchema
    Properties:
      ApiId: !GetAtt SimpleTodoApi.ApiId
      TypeName: Query
      FieldName: listTodos
      DataSourceName: !GetAtt TodoDataSource.Name
      Kind: UNIT
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const request = {
            operation: 'Scan',
            limit: ctx.args.limit ? ctx.args.limit : 20,
          };
          if (ctx.args.nextToken) {
            request.nextToken = ctx.args.nextToken;
          }
          return request;
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return {
            items: ctx.result.items ? ctx.result.items : [],
            nextToken: ctx.result.nextToken ? ctx.result.nextToken : null,
          };
        }

  TodosByOwnerResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoSchema
    Properties:
      ApiId: !GetAtt SimpleTodoApi.ApiId
      TypeName: Query
      FieldName: todosByOwner
      DataSourceName: !GetAtt TodoDataSource.Name
      Kind: UNIT
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const request = {
            operation: 'Query',
            index: 'byOwner',
            query: {
              expression: '#owner = :owner',
              expressionNames: { '#owner': 'owner' },
              expressionValues: util.dynamodb.toMapValues({ ':owner': ctx.args.owner }),
            },
            scanIndexForward: false,
            limit: ctx.args.limit ? ctx.args.limit : 20,
          };
          if (ctx.args.nextToken) {
            request.nextToken = ctx.args.nextToken;
          }
          return request;
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return {
            items: ctx.result.items ? ctx.result.items : [],
            nextToken: ctx.result.nextToken ? ctx.result.nextToken : null,
          };
        }

Outputs:
  GraphQLApiId:
    Description: ID of the SimpleTodoAPI AppSync API
    Value: !GetAtt SimpleTodoApi.ApiId
  GraphQLApiUrl:
    Description: GraphQL endpoint URL of the SimpleTodoAPI
    Value: !GetAtt SimpleTodoApi.GraphQLUrl
  GraphQLApiKey:
    Description: API key used to call the SimpleTodoAPI for testing
    Value: !GetAtt SimpleTodoApiKey.ApiKey
  TodoTableName:
    Description: Name of the DynamoDB table holding to-do items
    Value: !Ref TodoTable
  TodoTableArn:
    Description: ARN of the DynamoDB table holding to-do items
    Value: !GetAtt TodoTable.Arn
  AppSyncServiceRoleArn:
    Description: ARN of the IAM role AppSync assumes to access the table
    Value: !GetAtt AppSyncDynamoDBRole.Arn
